function lfNum(v,n=2){return v!==null&&v!==undefined&&v!==''&&Number.isFinite(+v)?(+v).toFixed(n):'--'}
function lfMean(a){a=a.filter(Number.isFinite);return a.length?a.reduce((s,v)=>s+v,0)/a.length:NaN}
