function lfLane(){const ls=obj('lane_state')||{},c=ls.corridor||{};return {left:String(c.left_status||'UNKNOWN').toUpperCase(),right:String(c.right_status||'UNKNOWN').toUpperCase(),rec:String(c.recommendation||ls.state||'--').toUpperCase(),leftGap:+c.left_gap_px,rightGap:+c.right_gap_px,drivable:Boolean(c.drivable_detected??ls.drivable_valid??ls.valid),laneMask:Boolean(c.lane_mask_detected),rawMask:Boolean(c.raw_lane_mask_detected),leftValid:c.left_valid===true||+c.left_samples>0,rightValid:c.right_valid===true||+c.right_samples>0,leftLatch:Boolean(c.left_recenter_latched),rightLatch:Boolean(c.right_recenter_latched),mode:String(c.evidence_mode||'--'),internalIgnored:Boolean(c.internal_lane_ignored)}}
function lfLaneMatch(key,s=lfLane()){
  const c=LF43_CONDS.find(x=>x.key===key);if(!c)return false;
  if(key==='gray')return !s.drivable&&!s.laneMask&&(s.left==='UNKNOWN'||s.left==='GRAY')&&(s.right==='UNKNOWN'||s.right==='GRAY');
  return s.left===c.left&&s.right===c.right&&s.rec===c.rec;
}
function lfCapture(kind='generic',note=''){
  const img=lfSourceImage();if(!img||!img.complete||!img.naturalWidth)return null;
  const maxW=720,scale=Math.min(1,maxW/img.naturalWidth),w=Math.round(img.naturalWidth*scale),h=Math.round(img.naturalHeight*scale),foot=70,c=document.createElement('canvas');c.width=w;c.height=h+foot;const x=c.getContext('2d');
  x.fillStyle='#071113';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,w,h);
  if(kind==='human'){const z=lfHuman(),sx=w/img.naturalWidth,sy=h/img.naturalHeight;z.humans.forEach((d,i)=>{const norm=Math.max(Math.abs(+d.x1||0),Math.abs(+d.x2||0),Math.abs(+d.y1||0),Math.abs(+d.y2||0))<=1.2,x1=(norm?(+d.x1||0)*img.naturalWidth:(+d.x1||0))*sx,y1=(norm?(+d.y1||0)*img.naturalHeight:(+d.y1||0))*sy,x2=(norm?(+d.x2||0)*img.naturalWidth:(+d.x2||0))*sx,y2=(norm?(+d.y2||0)*img.naturalHeight:(+d.y2||0))*sy;x.strokeStyle=i===0?'#ffc86b':'#48e0a4';x.lineWidth=i===0?4:2;x.strokeRect(x1,y1,Math.max(1,x2-x1),Math.max(1,y2-y1));x.fillStyle=x.strokeStyle;x.font='700 14px sans-serif';x.fillText('MANUSIA '+lfNum(d.score,3),Math.max(4,x1+4),Math.max(18,y1-5))})}
  if(kind==='lane'){const s=lfLane();x.fillStyle='rgba(4,12,14,.8)';x.fillRect(12,12,310,58);x.font='800 16px sans-serif';x.fillStyle='#fff';x.fillText('KIRI '+s.left+'  |  KANAN '+s.right,24,36);x.font='700 13px sans-serif';x.fillText('Decision: '+s.rec,24,58)}
  x.fillStyle='#071113';x.fillRect(0,h,w,foot);x.fillStyle='#e5f4f3';x.font='800 16px sans-serif';x.fillText(note||'FINAL DATASET PERSEPSI',14,h+26);x.fillStyle='#8fa8a9';x.font='12px sans-serif';x.fillText(new Date().toISOString(),14,h+50);
  return c.toDataURL('image/jpeg',.72);
}
