function lfGraph44(metric,title){const c=document.createElement('canvas');c.width=1100;c.height=550;const x=c.getContext('2d');x.fillStyle='#071113';x.fillRect(0,0,c.width,c.height);x.fillStyle='#e5f4f3';x.font='800 23px sans-serif';x.fillText(title,35,42);const all=lf.f44.rows.filter(r=>Number.isFinite(+r[metric])),max=Math.max(1,...all.map(r=>+r[metric]))*1.1,left=70,top=80,w=970,h=380;LF44_CONDS.forEach((cond,si)=>{const a=lf44Rows(cond.key).filter(r=>Number.isFinite(+r[metric]));x.strokeStyle=['#48e0a4','#ffc86b','#67b7ff'][si];x.lineWidth=2;x.beginPath();a.forEach((r,i)=>{const px=left+(r.sec-1)/59*w,py=top+h-(+r[metric]/max)*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();x.fillStyle=x.strokeStyle;x.fillText(cond.label,760,55+si*18)});return c.toDataURL('image/png')}
