function lfPose(){const p=obj('esc_odom');return{x:lfValue(p.x),y:lfValue(p.y),yaw:lfValue(p.yaw)}}
function lfDist(a,b){return a&&b&&[a.x,a.y,b.x,b.y].every(Number.isFinite)?Math.hypot(a.x-b.x,a.y-b.y):NaN}
function lf45Ready(mode,key){const reasons=[],ts=obj('trajectory_safety_state'),cfg=configData('trajectory_safety')?.trajectory_safety_supervisor?.ros__parameters||{},speed=lfValue(raw('esc_drive_actual'));
 for(const k of ['connected.camera','camera_healthy','connected.esc_feedback','connected.esc_ready','system.motion_ready'])if(!bool(raw(k)))reasons.push(k);
 if(!bool(raw('perception_inference_enabled')))reasons.push('YOLOPv2 OFF');if(bool(raw('system.estop'))||bool(raw('vesc_maintenance_active')))reasons.push('E-stop / maintenance');
 for(const k of ['trajectory_safety_state','esc_odom','esc_drive_actual','esc_steer_actual','lane_state','obstacle_metrics'])if(!channelFresh(k,k==='lane_state'||k==='obstacle_metrics'?2.5:1))reasons.push(k+' stale');
 if(!Number.isFinite(speed)||Math.abs(speed)>.03)reasons.push('feedback kendaraan belum diam');
 if(ts.metric_obstacle_safety!==true||ts.lane_safety_enabled!==true||cfg.commissioning_bypass_enabled===true)reasons.push('safety runtime belum aktif');
 if(ts.final_trial_supported!==true)reasons.push('pengawas trial aman belum aktif');
 if(mode==='obstacle'&&(!lfHuman().fresh||!lfHuman().best))reasons.push('manusia belum terdeteksi');
 if(mode==='lane'&&key&&!lf45InitialLaneMatch(key))reasons.push('kondisi lane belum sesuai');
 return{ok:!reasons.length,reasons};
}
function lf45InitialLaneMatch(k){const s=lfLane();if(k==='center')return s.left==='GREEN'&&s.right==='GREEN';if(k==='left_yellow')return s.left==='YELLOW'&&s.right==='GREEN';if(k==='right_yellow')return s.left==='GREEN'&&s.right==='YELLOW';if(k==='left_red')return s.left==='RED'&&s.right==='GREEN';if(k==='right_red')return s.left==='GREEN'&&s.right==='RED';return false}
function lf45Sample(){const ts=obj('trajectory_safety_state')||{},s=lfLane(),h=lfHuman(),metrics=obj('obstacle_metrics').detections,hm=Array.isArray(metrics)?metrics.filter(d=>d?.confirmed!==false&&+d.class_id===0&&Number.isFinite(+d.forward_m)&&+d.forward_m>=0).sort((a,b)=>+a.forward_m-+b.forward_m)[0]:null,near=obj('near_field_state')||{},nearSeen=near.raw_candidate===true&&+near.raw_class_id===0;return{t:Date.now()-lfActive.goAt,pose:lfPose(),decision:String(ts.decision||ts.raw||'--').toUpperCase(),navV:+ts.nav_v,outV:+ts.out_v,outW:+ts.out_w,speedTarget:lfValue(raw('esc_drive_target')),speedActual:lfValue(raw('esc_drive_actual')),steerTarget:Number.isFinite(+raw('esc_steer_target'))?+raw('esc_steer_target')*180/Math.PI:NaN,steerActual:Number.isFinite(+raw('esc_steer_actual'))?+raw('esc_steer_actual')*180/Math.PI:NaN,lane:s,obstacleSeen:!!hm||nearSeen,obstacleDistance:hm?+hm.forward_m:NaN,confidence:hm&&Number.isFinite(+hm.score)?+hm.score:nearSeen&&Number.isFinite(+near.confidence)?+near.confidence:h.best?+h.best.score:NaN}}
async function lf45Start(){
 if(lfActive)return toast('Trial sedang aktif.',true);const mode=lf.f45.tab||'obstacle',key=mode==='obstacle'?$('lf45ObsDistance').value:$('lf45LaneCondition').value;
 if(!$('lf45Ready')?.checked)return toast('Centang konfirmasi area aman dan kendaraan diam.',true);
 const r=lf45Ready(mode,mode==='lane'?key:null);if(!r.ok)return toast('Belum READY: '+r.reasons.join(', '),true);
 lfActive={type:'45',mode,key,start:Date.now(),goAt:0,phase:'starting',samples:[],token:crypto.randomUUID(),gap0:sseGapCount};lfRefresh();
 try{const j=await post('/api/perception/final-trial/start',{mode,condition:key,token:lfActive.token},true);if(!j.ok)throw Error(j.message||'Trial ditolak');lfActive.phase='countdown';lfActive.countdown=3;lfTimer=setInterval(lf45Monitor,250)}catch(e){lfActive=null;toast(e.message,true);lfRender()}
}
function lf45RuntimeFaultDecision(d){return /STALE|DISCONNECTED|UNHEALTHY|UNAVAILABLE|NONFINITE|BLOCKED|LANE_LOST/.test(String(d))}
function lf45ValidStopDecision(d){return /^(IMMEDIATE_COMMAND_HARD_STOP|NO_SAFE_CORRIDOR_STOP|AVOIDANCE_NOT_ENGAGED_STOP|DRIVABLE_SPACE_UNKNOWN_STOP|PERCEPTION_EMERGENCY_STOP)$/.test(String(d))}
function lf45ValidAvoidDecision(d){return /^(SEARCH_AVOIDANCE_(LEFT|RIGHT|BOTH)|AVOID_(LEFT|RIGHT))$/.test(String(d||'').toUpperCase())}
async function lf45Monitor(){
 const a=lfActive;if(!a||a.type!=='45'||a.busy)return;a.busy=true;
 try{const r=await post('/api/perception/final-trial/heartbeat',{token:a.token},true);if(lfActive!==a)return;
 if(!r.ok)throw Error(r.message||'Heartbeat trial gagal');const t=r.trial||{};a.phase=t.phase||a.phase;a.countdown=t.countdown;a.goAt=t.go_at_ms?+t.go_at_ms+serverDelta:0;a.backend=t;
 if(t.phase==='running'||t.phase==='stopping'){const sample=lf45Sample(),seq=updated.esc_odom;if(seq!==a.lastSample){a.lastSample=seq;a.samples.push({...sample,trial:t})}}
 if(['complete','invalid','failed','aborted'].includes(t.phase))return lf45Finish(t.phase,t);
 if(sseGapCount!==a.gap0)throw Error('Celah stream SSE');
 }catch(e){if(lfActive===a)await lf45Finish('INVALID: '+e.message)}finally{a.busy=false;lfRefresh()}
}
async function lf45Finish(reason,trial=null){
 const a=lfActive;if(!a||a.type!=='45')return;clearInterval(lfTimer);lfTimer=null;
 if(!trial){try{const r=await post('/api/perception/final-trial/stop',{token:a.token,reason},true);trial=r.trial}catch(e){toast('Komunikasi putus; watchdog server menghentikan trial.',true)}}
 lfActive=null;const valid=trial?.phase==='complete'||trial?.phase==='failed',result=valid?(trial.phase==='complete'?'PASS':'FAIL'):'INVALID';
 const samples=a.samples,errors=samples.filter(x=>Number.isFinite(x.steerTarget)&&Number.isFinite(x.steerActual)).map(x=>(x.steerTarget-x.steerActual)**2);
 const row={...trial,result,valid,distance:a.mode==='obstacle'?+a.key:undefined,condition:a.mode==='lane'?a.key:undefined,label:LF45_LANE.find(c=>c.key===a.key)?.label,response:trial?.response||reason,decision:trial?.response||reason,responseMs:trial?.response_ms??null,recoveryMs:trial?.recovery_ms??null,duration:trial?.duration_s??0,travel:trial?.travel_m??null,stopped:trial?.stopped===true,cleared:trial?.cleared===true,steeringRMSE:errors.length?Math.sqrt(lfMean(errors)):null};
 const group=lf.f45[a.mode];group.attempts=group.attempts||[];group.attempts.push({at:new Date().toISOString(),key:a.key,row,series:samples});
 if(valid){group.rows=group.rows.filter(r=>a.mode==='obstacle'?r.distance!==+a.key:r.condition!==a.key);group.rows.push(row);group.series[a.key]=samples;group.evidence[a.key]=lfCapture(a.mode==='obstacle'?'human':'lane',row.label||'Manusia '+a.key+' m')}
 lfSave();toast('4.5 '+result+' • '+(trial?.reason||reason),result!=='PASS');lfRender();
}
function lf45ResetOne(){if(lfActive)return toast('Abort trial aktif sebelum reset.',true);if(lf.f45.tab==='obstacle'){const d=+$('lf45ObsDistance').value;if(!confirm('Reset obstacle '+d+' m?'))return;lf.f45.obstacle.rows=lf.f45.obstacle.rows.filter(r=>+r.distance!==d);delete lf.f45.obstacle.evidence[d];delete lf.f45.obstacle.series[d]}else{const k=$('lf45LaneCondition').value;if(!confirm('Reset '+(LF45_LANE.find(c=>c.key===k)?.label||k)+'?'))return;lf.f45.lane.rows=lf.f45.lane.rows.filter(r=>r.condition!==k);delete lf.f45.lane.evidence[k];delete lf.f45.lane.series[k]}lfSave();lfRender()}
function lf45ResetAll(){if(lfActive)return toast('Abort trial aktif sebelum reset.',true);if(lf.f45.tab==='obstacle'){if(!confirm('Reset seluruh obstacle 4.5?'))return;lf.f45.obstacle={rows:[],evidence:{},series:{}}}else{if(!confirm('Reset seluruh Lane Safety 4.5?'))return;lf.f45.lane={rows:[],evidence:{},series:{}}}lfSave();lfRender()}
function lf45BarPng(title,labels,values,unit=''){const c=document.createElement('canvas');c.width=1100;c.height=560;const x=c.getContext('2d'),left=80,top=85,w=970,h=350,finite=values.filter(Number.isFinite),max=Math.max(1,...finite)*1.15;x.fillStyle='#071113';x.fillRect(0,0,c.width,c.height);x.fillStyle='#e5f4f3';x.font='800 23px sans-serif';x.fillText(title,35,42);x.strokeStyle='#355052';x.fillStyle='#8fa8a9';x.font='12px sans-serif';for(let i=0;i<=4;i++){const y=top+h-i*h/4;x.beginPath();x.moveTo(left,y);x.lineTo(left+w,y);x.stroke();x.fillText(lfNum(max*i/4,unit==='ms'?0:2)+(unit?' '+unit:''),12,y+4)}const gap=w/Math.max(1,labels.length),bw=gap*.55;labels.forEach((lab,i)=>{const v=+values[i],bh=Number.isFinite(v)?Math.max(2,v/max*h):0,px=left+i*gap+(gap-bw)/2,py=top+h-bh;x.fillStyle='#48e0a4';x.fillRect(px,py,bw,bh);x.fillStyle='#d8eeee';x.font='11px sans-serif';if(Number.isFinite(v))x.fillText(lfNum(v,unit==='ms'?0:2),px,py-6);x.save();x.translate(px+bw/2,top+h+18);x.rotate(-.32);x.fillText(String(lab),0,0);x.restore()});return c.toDataURL('image/png')}
