function lfRefresh(){
  if(!lfIsActive())return;const p=obj('perception_performance'),h=lfHuman(),s=lfLane(),src=lfSourceImage(),prev=$('expCameraImage');setText('lfPreviewStatus',src&&src.complete&&src.naturalWidth?'LIVE':'WAIT');const strip=$('lfLiveStrip');if(strip)strip.textContent='Pipeline '+lfNum(p.pipeline_fps,2)+' FPS • Inference '+lfNum(p.inference_ms,1)+' ms • Human '+(h.best?lfNum(h.best.score,3):'--')+' • Lane '+s.left+'/'+s.right+' • '+s.rec;
  if($('lf41Camera'))setText('lf41Camera',bool(raw('camera_healthy'))?'HEALTHY':'WAIT');if($('lf41Infer'))setText('lf41Infer',bool(raw('perception_inference_enabled'))?'ACTIVE':'OFF');if($('lf41Fps'))setText('lf41Fps',lfNum(p.pipeline_fps,2));if($('lf41InfMs'))setText('lf41InfMs',lfNum(p.inference_ms,1)+' ms');
  setText('lf42Class',h.best?'MANUSIA':'TIDAK TERDETEKSI');setText('lf42ConfidenceLive',h.fresh&&h.best?lfNum(h.best.score,3):'--');setText('lf42Threshold',lfNum(h.threshold,3));setText('lf42Source',h.fresh?(obj('semantic_detections').source||'SEMANTIC')+' • FRESH':'SEMANTIC • STALE');setText('lf42Estimate',lfNum(h.best?.calibrated_forward_m,2)+' m');setText('lf42Error',h.best?.calibrated_forward_m!=null?lfNum(h.best.calibrated_forward_m-(+$('lf42Distance')?.value||1),2)+' m':'--');if($('lf42Confidence')){const d=+$('lf42Distance')?.value||1,c=lf.f42.rows.filter(r=>+r.distance===d&&Number.isFinite(r.confidence)).slice(-5).map(r=>r.confidence);setText('lf42Confidence','Confidence '+(h.best?lfNum(h.best.score,3):'--')+' • stabil '+lfNum(lfMean(c),3))}
  if($('lf43Expected')){const k=$('lf43Condition')?.value||'center',c=LF43_CONDS.find(x=>x.key===k);setText('lf43Expected','Expected: LEFT '+c.left+' • RIGHT '+c.right+' • '+c.rec);setText('lf43Live','Aktual '+s.left+'/'+s.right+' • '+s.rec)}
  if($('lf44Fps')){setText('lf44Fps',lfNum(p.pipeline_fps,2)+' FPS');setText('lf44Inf',lfNum(p.inference_ms,1)+' ms');setText('lf44Age',lfNum(p.frame_age_ms,1)+' ms')}
  if(lfActive){const e=(Date.now()-lfActive.start)/1000;if(lfActive.type==='42'){setText('lf42Status','PENGAMBILAN AKTIF');setText('lf42Counter',lfActive.done+' / 10');setText('lf42Time',Math.max(0,Math.ceil(30-e))+' s')}if(lfActive.type==='43'){setText('lf43Status','PENGAMBILAN AKTIF');setText('lf43Counter',lfActive.done+' / 10');setText('lf43Time',Math.max(0,Math.ceil(30-e))+' s')}if(lfActive.type==='44')setText('lf44Time',Math.min(60,Math.floor(e))+' / 60 s');if(lfActive.type==='45'){setText('lf45Countdown',lfActive.phase==='countdown'?String(lfActive.countdown):'GO • CONTROL ACTIVE');const last=lfActive.samples?.[lfActive.samples.length-1];if(last)setText('lf45Result',(lfActive.mode==='obstacle'?'Decision '+last.decision+' • obstacle '+lfNum(last.obstacleDistance,2)+' m':'Lane '+last.lane.left+'/'+last.lane.right+' • '+last.decision)+' • speed '+lfNum(last.speedActual,2)+' m/s')}}
  lfLockControls();lfDrawOverlay()
}
function lfDrawOverlay(){const cv=$('lfOverlay'),img=$('expCameraImage'),stage=$('lfPreviewStage');if(!cv||!img||!img.naturalWidth||!stage)return;const sr=stage.getBoundingClientRect();if(sr.width<2||sr.height<2)return;const dpr=window.devicePixelRatio||1,stageW=sr.width,stageH=sr.height,scale=Math.min(stageW/img.naturalWidth,stageH/img.naturalHeight),renderW=img.naturalWidth*scale,renderH=img.naturalHeight*scale,offX=(stageW-renderW)/2,offY=(stageH-renderH)/2;cv.width=Math.round(stageW*dpr);cv.height=Math.round(stageH*dpr);const x=cv.getContext('2d');x.clearRect(0,0,cv.width,cv.height);if(['F4.1','F4.2','F4.5'].includes(selectedExperiment?.id)){const ds=lfHuman().humans,sx=scale*dpr,sy=scale*dpr,ox=offX*dpr,oy=offY*dpr;ds.forEach((d,i)=>{const norm=Math.max(Math.abs(+d.x1||0),Math.abs(+d.x2||0),Math.abs(+d.y1||0),Math.abs(+d.y2||0))<=1.2,x1=ox+(norm?(+d.x1||0)*img.naturalWidth:(+d.x1||0))*sx,y1=oy+(norm?(+d.y1||0)*img.naturalHeight:(+d.y1||0))*sy,x2=ox+(norm?(+d.x2||0)*img.naturalWidth:(+d.x2||0))*sx,y2=oy+(norm?(+d.y2||0)*img.naturalHeight:(+d.y2||0))*sy;x.strokeStyle=i===0?'#ffc86b':'#48e0a4';x.lineWidth=(i===0?3:2)*dpr;x.strokeRect(x1,y1,x2-x1,y2-y1);x.fillStyle=x.strokeStyle;x.font=(12*dpr)+'px sans-serif';x.fillText('MANUSIA '+lfNum(d.score,2),x1+4*dpr,Math.max(15*dpr,y1-4*dpr))})}if(['F4.3','F4.5'].includes(selectedExperiment?.id)){const s=lfLane();x.fillStyle='rgba(4,12,14,.75)';x.fillRect(10*dpr,10*dpr,320*dpr,48*dpr);x.fillStyle='#fff';x.font=(13*dpr)+'px sans-serif';x.fillText('KIRI '+s.left+' • KANAN '+s.right+' • '+s.rec,20*dpr,38*dpr)}}
function lfValue(v){return v===null||v===undefined||v===''?NaN:Number(v)}
function lfLatency(){const ns=lfValue(obj('lane_state').stamp_ns),ms=Date.now()-serverDelta-ns/1e6;return Number.isFinite(ms)&&ms>=0&&ms<5000?ms:NaN}
function lfSourceKey(channel){const v=obj(channel);return String(v.stamp_ns||v.frame_stamp_ns||v.frame_sequence||updated[channel]||'')}
function lfLockControls(){if(!lfIsActive())return;setText('lfGlobalState',lfSaveError?'SAVE FAILED':lfActive?'RECORDING':'READY');qa('button,select,input',$('perLockedBab4Panel')).forEach(e=>{if(e.id==='lfCancel'||e.id==='lf45Abort'){e.disabled=!lfActive;return}if(lfActive){if(!e.dataset.lfWasDisabled)e.dataset.lfWasDisabled=e.disabled?'1':'0';e.disabled=true}else if(e.dataset.lfWasDisabled){e.disabled=e.dataset.lfWasDisabled==='1';delete e.dataset.lfWasDisabled}})}
function lfBegin(type,key){
 const start=Date.now();lfActive={type,key,distance:type==='42'?+key:undefined,condition:key,start,mono:performance.now(),done:0,best:-1,gap0:sseGapCount,last:{},raw:[],buckets:Array.from({length:60},()=>({perf:[],frames:0}))};
 for(const k of ['semantic_detections','lane_state','perception_performance','raw_detections'])lfActive.last[k]=lfSourceKey(k);
 lfActive.config=lfConfigSnapshot();lfTimer=setInterval(()=>{const a=lfActive;if(!a||a.type!==type)return;const elapsed=performance.now()-a.mono;if(elapsed>=(type==='44'?60000:30000))lfCompleteAcquisition(type==='44'?'duration':'timeout');else lfRefresh()},100);lfRefresh();
}
function lfIngest(delta){
 const a=lfActive;if(!a||a.type==='45')return;const elapsed=performance.now()-a.mono;
 if(elapsed<0||elapsed>=(a.type==='44'?60000:30000))return;
 const accept=k=>{if(!Object.hasOwn(delta,k)||!channelFresh(k,2.5))return false;const seq=lfSourceKey(k);if(!seq||seq===a.last[k])return false;a.last[k]=seq;return true};
 if(a.type==='42'&&accept('semantic_detections')){
  if(elapsed<a.done*3000)return;const h=lfHuman(),b=h.best,conf=lfValue(b?.score),detected=!!b&&Number.isFinite(conf),estimate=lfValue(b?.calibrated_forward_m),p=obj('perception_performance');
  lf.f42.rows.push({at:new Date().toISOString(),sourceStamp:a.last.semantic_detections,distance:a.distance,sample:++a.done,detected,classId:b?.class_id??null,className:b?.class_name||'',confidence:detected?conf:null,threshold:Number.isFinite(h.threshold)?h.threshold:null,estimatedDistance:Number.isFinite(estimate)?estimate:null,distanceError:Number.isFinite(estimate)?estimate-a.distance:null,candidates:h.humans.length,source:obj('semantic_detections').source||'SEMANTIC',pipeline:lfValue(p.pipeline_fps),inference:lfValue(obj('semantic_detections').inference_ms),frameAge:lfValue(p.frame_age_ms)});
  if(conf>a.best){a.best=conf;lf.f42.evidence[a.distance]=lfCapture('human','Manusia '+a.distance+' m • confidence '+lfNum(conf,3))}
 }
 if(a.type==='43'&&accept('lane_state')){
  if(elapsed<a.done*3000)return;const l=lfLane(),c=LF43_CONDS.find(c=>c.key===a.key),match=lfLaneMatch(a.key,l);
  lf.f43.rows.push({...l,at:new Date().toISOString(),sourceStamp:a.last.lane_state,condition:a.key,sample:++a.done,expectedLeft:c.left,expectedRight:c.right,expectedRecommendation:c.rec,match});
  if(!lf.f43.evidence[a.key]||match&&!a.bestMatch){lf.f43.evidence[a.key]=lfCapture('lane',c.label);a.bestMatch=match}
 }
 if(a.type==='44'){
  const bucket=a.buckets[Math.floor(elapsed/1000)];
  if(accept('perception_performance')){const p=obj('perception_performance'),sample={at:new Date().toISOString(),sec:Math.floor(elapsed/1000)+1,sourceStamp:a.last.perception_performance,pipeline:lfValue(p.pipeline_fps),inference:lfValue(p.inference_ms),process:lfValue(p.pipeline_ms),age:lfValue(p.frame_age_ms),lat:lfLatency()};bucket.perf.push(sample);a.raw.push(sample)}
  if(accept('raw_detections'))bucket.frames++;
 }
 if(a.done>=10)lfCompleteAcquisition('complete');else{lfSave();lfRefresh()}
}
function lfCompleteAcquisition(reason){
 const a=lfActive;if(!a||a.type==='45')return;clearInterval(lfTimer);lfTimer=null;
 const group=lf['f'+a.type];group.attempts=group.attempts||[];group.config=group.config||{};group.config[a.key]=a.config;
 if(a.type==='44'){
  const rows=a.buckets.map((b,i)=>{const fields=['pipeline','inference','process','age','lat'],finite=b.perf.length>0&&b.perf.every(p=>fields.every(k=>Number.isFinite(p[k])&&p[k]>=0));return{condition:a.key,sec:i+1,samples:b.perf.length,frames:b.frames,pipeline:lfMean(b.perf.map(p=>p.pipeline)),inference:lfMean(b.perf.map(p=>p.inference)),process:lfMean(b.perf.map(p=>p.process)),age:lfMean(b.perf.map(p=>p.age)),latency:lfMean(b.perf.map(p=>p.lat)),valid:finite&&b.frames>0&&sseGapCount===a.gap0}});
  const valid=reason==='duration'&&rows.every(r=>r.valid);group.rows=group.rows.filter(r=>r.condition!==a.key).concat(rows);group.complete[a.key]=valid;group.raw=group.raw||{};group.raw[a.key]=a.raw;group.evidence[a.key]=lfCapture('human',LF44_CONDS.find(c=>c.key===a.key).label);group.attempts.push({key:a.key,reason,valid,rows,raw:a.raw,gaps:sseGapCount-a.gap0});toast(valid?'4.4 VALID • 60 detik':'4.4 INVALID • data diagnostik disimpan',!valid);
 }else{
  const rows=group.rows.filter(r=>a.type==='42'?r.distance===a.distance:r.condition===a.key),valid=reason==='complete'&&a.done===10&&sseGapCount===a.gap0;
  group.attempts.push({key:a.key,reason,valid,rows,gaps:sseGapCount-a.gap0});
  if(!valid){group.rows=group.rows.filter(r=>a.type==='42'?r.distance!==a.distance:r.condition!==a.key);delete group.evidence[a.key]}
  else if(!group.evidence[a.key])group.evidence[a.key]=lfCapture(a.type==='42'?'human':'lane','Kondisi '+a.key);
  toast(valid?'4.'+a.type[1]+' selesai • 10 sampel baru':'Pengambilan tidak lengkap. Data diagnostik tersimpan.',!valid);
 }
 lfActive=null;lfSave();lfRender();
}
function lfCancel(){if(lfActive?.type==='45')return lf45Finish('ABORT');if(lfActive)lfCompleteAcquisition('aborted')}
function lfYaml(v,indent=0){const pad=' '.repeat(indent);if(v===null||typeof v!=='object')return JSON.stringify(v??null);return Object.entries(v).map(([k,x])=>pad+JSON.stringify(k)+':'+(x&&typeof x==='object'?'\n'+lfYaml(x,indent+2):' '+JSON.stringify(x??null))).join('\n')+'\n'}
function lfPlot(title,series,unit='',xTitle='Waktu [s]'){const c=document.createElement('canvas');c.width=1200;c.height=700;const x=c.getContext('2d'),L=100,T=120,W=1000,H=440;const points=series.flatMap(s=>s.points).filter(p=>p.every(Number.isFinite)),ys=points.map(p=>p[1]),xs=points.map(p=>p[0]),lo=Math.min(0,...ys),hi=Math.max(1,...ys),xmin=Math.min(0,...xs),xmax=Math.max(1,...xs);x.fillStyle='#fff';x.fillRect(0,0,1200,700);x.fillStyle='#111';x.font='bold 23px sans-serif';x.fillText(title,40,40);const colors=['#127c60','#bf671d','#265caa','#8e4392','#d32742','#597522'];x.font='14px sans-serif';for(let i=0;i<=5;i++){const y=T+H-i*H/5;x.strokeStyle='#d9dfe5';x.beginPath();x.moveTo(L,y);x.lineTo(L+W,y);x.stroke();x.fillStyle='#222';x.fillText((lo+(hi-lo)*i/5).toFixed(2),15,y+5)}for(let i=0;i<=5;i++){const px=L+W*i/5;x.fillText((xmin+(xmax-xmin)*i/5).toFixed(1),px-12,T+H+25)}series.forEach((s,j)=>{x.strokeStyle=colors[j%colors.length];x.fillStyle=x.strokeStyle;x.fillText(s.label,45+(j%2)*550,70+Math.floor(j/2)*18);x.lineWidth=2.5;x.beginPath();let first=true;s.points.forEach(([a,b])=>{if(!Number.isFinite(a)||!Number.isFinite(b)){first=true;return}const px=L+(a-xmin)/(xmax-xmin)*W,py=T+H-(b-lo)/(hi-lo)*H;if(first)x.moveTo(px,py);else x.lineTo(px,py);first=false});x.stroke()});x.fillStyle='#222';x.fillText(unit,20,110);x.fillText(xTitle,540,625);return c.toDataURL('image/png')}
async function lfMontage(evidence,spec,title){const cols=spec.length===6?3:5,rows=Math.ceil(spec.length/cols),w=400,h=310,c=document.createElement('canvas');c.width=cols*w;c.height=80+rows*h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#111';x.font='bold 26px sans-serif';x.fillText(title,24,42);for(let i=0;i<spec.length;i++){const item=spec[i],px=(i%cols)*w,py=80+Math.floor(i/cols)*h;x.fillStyle='#111';x.font='bold 14px sans-serif';const words=item.label.split(' ');let line='',yy=py+20;for(const word of words){if(x.measureText(line+' '+word).width>w-25){x.fillText(line,px+12,yy);yy+=18;line=word}else line+=(line?' ':'')+word}x.fillText(line,px+12,yy);const url=evidence[item.key];if(url)await new Promise(resolve=>{const im=new Image();im.onload=()=>{const scale=Math.min((w-24)/im.width,(h-70)/im.height);x.drawImage(im,px+12,py+60,im.width*scale,im.height*scale);resolve()};im.onerror=resolve;im.src=url})}return c.toDataURL('image/png')}


function lfChart44(metrics,title){return lfPlot(title,LF44_CONDS.flatMap(c=>metrics.map(m=>({label:c.label+' / '+m,points:lf44Rows(c.key).map(r=>[r.sec,lfValue(r[m])])}))),metrics[0]==='pipeline'?'FPS':'ms')}
async function lf45Extra(mode){const g=lf.f45[mode],root=mode==='obstacle'?'01_obstacle_response/':'02_lane_safety_response/',spec=mode==='obstacle'?LF42_DIST.map(d=>({key:d,label:d+' meter'})):LF45_LANE.map(c=>({key:c.key,label:c.label})),series=metric=>Object.entries(g.series).map(([k,a])=>({label:k,points:a.map(s=>[s.t/1000,lfValue(s[metric])])}));return [{name:root+'speed_response.png',data:lfDataBytes(lfPlot('Respons Kecepatan Target / Aktual', [...series('speedTarget').map(x=>({...x,label:x.label+' target'})),...series('speedActual').map(x=>({...x,label:x.label+' aktual'}))],'m/s'))},{name:root+'steering_response.png',data:lfDataBytes(lfPlot('Respons Sudut Steering Target / Aktual',[...series('steerTarget').map(x=>({...x,label:x.label+' target'})),...series('steerActual').map(x=>({...x,label:x.label+' aktual'}))],'derajat'))},{name:root+'evidence_'+(mode==='obstacle'?'1-5m':'5_conditions')+'.png',data:lfDataBytes(await lfMontage(g.evidence,spec,'Dokumentasi Respons Kendaraan'))},{name:root+'attempts.json',data:JSON.stringify(g.attempts||[],null,2)},{name:'03_configuration/'+mode+'_safety_control_config.yaml',data:lfYaml(JSON.parse(lfConfigSnapshot()))}]}
async function lfLowerEvidence(type,box){
 const group=lf['f'+type];if(!group.rows.length)return;
 const heads=type==='42'?['Waktu','Jarak [m]','Sampel','Deteksi','Confidence']:type==='43'?['Waktu','Kondisi','Sampel','Kiri','Kanan','Rekomendasi','Sesuai']:['Kondisi','Detik','Sampel','Frame','FPS','Inferensi [ms]','Proses [ms]','Umur [ms]','Latensi [ms]','Valid'];
 const rows=group.rows.map(r=>type==='42'?[r.at,r.distance,r.sample,r.detected,lfNum(r.confidence,3)]:type==='43'?[r.at,LF43_CONDS.find(c=>c.key===r.condition)?.label,r.sample,r.left,r.right,r.rec,r.match]:[r.condition,r.sec,r.samples,r.frames,lfNum(r.pipeline),lfNum(r.inference),lfNum(r.process),lfNum(r.age),lfNum(r.latency),r.valid]);
 box.insertAdjacentHTML('beforeend','<h3>Data Pengujian</h3>'+lfTable(heads,rows)+'<div class="lf-graphs"></div>');const graphs=box.querySelector('.lf-graphs');
 const urls=type==='42'?[lfGraph42('rate'),lfGraph42('conf')]:type==='43'?[lfGraph43('success'),lfGraph43('gap')]:[lfChart44(['pipeline'],'Laju Pipeline'),lfChart44(['inference','process'],'Inferensi dan Pemrosesan'),lfChart44(['age','latency'],'Umur Frame dan Latensi')];
 urls.forEach(url=>{const im=new Image();im.src=url;im.alt='Grafik hasil pengujian';graphs.appendChild(im)});
 if(type!=='44'){const spec=type==='42'?LF42_DIST.map(d=>({key:d,label:d+' meter'})):LF43_CONDS.map(c=>({key:c.key,label:c.label})),url=await lfMontage(group.evidence,spec,'Dokumentasi Visual Pengujian');if(!box.isConnected)return;const im=new Image();im.src=url;im.alt='Montase semua kondisi';im.className='lf-montage';box.appendChild(im)}
}

